#!/usr/bin/env python3
"""qa-check.py — advisory pre-commit checks for specship QA artifacts.

Invoked best-effort by the pre-commit hook (the Wall). This script NEVER
blocks a commit: it prints warnings to stderr and always exits 0. The Wall
itself stays pure-bash; this Python layer adds the two soft QA guarantees
documented in dist/templates/HOW-TO-AUTHOR-QA.md:

  1. Append-only regression artifacts. If a commit modifies the `## Input`
     or `## Expected output` section of a regression artifact that was
     already approved (status: approved in HEAD), warn. Approved regressions
     are frozen — the correction pattern is retire + re-create, never mutate.

  2. Generated-test integrity. Every test generated by /qa carries an
     `# AUTO-GENERATED by specship /qa` header, a `§qa:<artifact>` linkback,
     and `# Content hash: <hash>` where the hash is sha256 of the source
     artifact's full text, first 16 hex chars (see dist/qa-generators/*).
     If a staged generated test's embedded hash no longer matches its source
     artifact, the artifact drifted without the test being regenerated (or
     the test was hand-edited). Warn and point at the fix.

The script reads git state directly so it can compare HEAD vs the staged
(index) version of each file. Run from the repo root (as a hook is).
"""

from __future__ import annotations

import re
import subprocess
import sys

REGRESSION_RE = re.compile(r"^regressions/.*\.md$")
ARTIFACT_RE = re.compile(r"^(regressions|scenarios|properties)/.*\.md$")
GENERATED_MARKER = "AUTO-GENERATED by specship /qa"
QA_REF_RE = re.compile(r"§qa:(\S+)")
FROZEN_SECTIONS = ("Input", "Expected output")
PLACEHOLDER_VALUES = {"", "<set-by-/qa-after-generation>", "<unknown>"}


def git(*args: str) -> str | None:
    """Run a git command, returning stdout text or None on any failure."""
    try:
        out = subprocess.run(
            ["git", *args],
            capture_output=True,
            text=True,
            check=True,
        )
        return out.stdout
    except (subprocess.CalledProcessError, FileNotFoundError, OSError):
        return None


def staged(diff_filter: str) -> list[str]:
    out = git("diff", "--cached", "--name-only", f"--diff-filter={diff_filter}")
    if not out:
        return []
    return [line for line in out.splitlines() if line.strip()]


def parse_frontmatter(text: str) -> tuple[dict, str]:
    """Return (frontmatter_dict, body_text). Empty dict if no frontmatter."""
    if not text.startswith("---\n"):
        return {}, text
    end = text.find("\n---\n", 4)
    if end < 0:
        return {}, text
    fm = {}
    for line in text[4:end].split("\n"):
        if ":" in line and not line.lstrip().startswith("#"):
            k, v = line.split(":", 1)
            fm[k.strip()] = v.strip()
    return fm, text[end + 5:]


def extract_section(body: str, heading: str) -> str:
    """Content between '## <heading>' and the next '## ' or EOF (matches the generators)."""
    pattern = re.compile(
        r"^##\s+" + re.escape(heading) + r"\s*\n(.*?)(?=^##\s|\Z)",
        re.MULTILINE | re.DOTALL,
    )
    m = pattern.search(body)
    return m.group(1).strip() if m else ""


def check_regressions() -> list[str]:
    """Feature 1: warn on edits to approved regression artifacts' frozen sections."""
    warnings: list[str] = []
    for path in staged("M"):
        if not REGRESSION_RE.match(path):
            continue
        head = git("show", f"HEAD:{path}")
        index = git("show", f":{path}")
        if head is None or index is None:
            continue
        head_fm, head_body = parse_frontmatter(head)
        if head_fm.get("status") != "approved":
            continue  # only frozen once approved
        _, index_body = parse_frontmatter(index)
        changed = [
            sec
            for sec in FROZEN_SECTIONS
            if extract_section(head_body, sec) != extract_section(index_body, sec)
        ]
        if changed:
            secs = " and ".join(f"'{s}'" for s in changed)
            warnings.append(
                f"{path}: {secs} changed, but this regression is approved "
                f"(append-only).\n"
                f"      Approved regression artifacts are frozen. To correct: "
                f"set status: retired with a retired_reason, then create a new "
                f"regression with the corrected input/output."
            )
    return warnings


def _generated_test_for_artifact(artifact_path: str) -> str | None:
    """The generated_test path recorded in a staged-modified artifact, if any."""
    index = git("show", f":{artifact_path}")
    if index is None:
        return None
    fm, _ = parse_frontmatter(index)
    gt = fm.get("generated_test", "").strip()
    return None if gt in PLACEHOLDER_VALUES else gt


def _exists_committed(path: str) -> bool:
    """True if the path will exist after this commit (in the index or worktree)."""
    if git("show", f":{path}") is not None:
        return True
    try:
        open(path, encoding="utf-8").close()
        return True
    except OSError:
        return False


def check_generated_tests(staged_all: set[str]) -> list[str]:
    """Feature 2: detect generated tests that fell out of sync with their artifact.

    The integrity signal is staging membership, not the embedded content hash:
    /qa rewrites an artifact's frontmatter (e.g. `generated_test`) after the
    hash is stamped, so a recomputed hash can't be trusted to stay matched. A
    legitimate change always stages the artifact AND its regenerated test
    together — so two asymmetries flag drift:

      - a generated test is modified without its source artifact (hand-edit), and
      - an artifact is modified without its recorded generated test being
        regenerated/staged (forgot to re-run /qa).
    """
    warnings: list[str] = []

    # Direction A: a generated test changed on its own.
    for path in staged("M"):
        content = git("show", f":{path}")
        if not content or GENERATED_MARKER not in content:
            continue
        ref_m = QA_REF_RE.search(content)
        if not ref_m:
            continue
        artifact_path = ref_m.group(1)
        if artifact_path not in staged_all:
            warnings.append(
                f"{path}: this is a /qa-generated test, but it was modified "
                f"without its source artifact ({artifact_path}) in the same "
                f"commit.\n"
                f"      Edit {artifact_path} and re-run /qa to regenerate, or "
                f"remove the AUTO-GENERATED header to claim manual ownership."
            )

    # Direction B: an artifact changed but its generated test did not.
    for path in staged("M"):
        if not ARTIFACT_RE.match(path):
            continue
        gt = _generated_test_for_artifact(path)
        if not gt or gt in staged_all:
            continue
        if _exists_committed(gt):
            warnings.append(
                f"{path}: artifact changed, but its generated test ({gt}) was "
                f"not regenerated in this commit.\n"
                f"      Re-run /qa so the test reflects the updated artifact."
            )
    return warnings


def main() -> int:
    if git("rev-parse", "--git-dir") is None:
        return 0  # not a git repo / git unavailable — nothing to do
    staged_all = set(staged("ACMR"))
    warnings = check_regressions() + check_generated_tests(staged_all)
    if warnings:
        print("\nspecship QA check (advisory — does not block this commit):", file=sys.stderr)
        for w in warnings:
            print(f"  ⚠ {w}", file=sys.stderr)
        print("", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())
